$d=$env:BL_DIR;$k=$env:BL_KEEP;$m=@{};foreach($f in @($env:BL_KNOWN,(Join-Path $d 'shipped-images.txt'))){if(Test-Path -LiteralPath $f){gc -LiteralPath $f|%{if($_ -match '^([0-9a-fA-F]{64})\s+(.+)$'){$m[$matches[2].Trim().ToLower()+'|'+$matches[1].ToLower()]=1}}}};$i=Join-Path $d 'images';if(Test-Path -LiteralPath $i){gci -LiteralPath $i -Recurse -File -Force|?{-not($_.Attributes -band 1024)}|%{$r='images/'+$_.FullName.Substring($i.Length+1).Replace('\','/');$h=(Get-FileHash -LiteralPath $_.FullName).Hash.ToLower();if(-not $m[$r.ToLower()+'|'+$h]){$t=Join-Path $k $r;$null=md (Split-Path $t) -Force;Move-Item -LiteralPath $_.FullName $t}}}
